// 缩放范围：最小显示 1%（display zoom），最大 raw zoom 3x
// 说明：CanvasState.zoom 是 raw zoom；显示百分比 = raw / baseZoom
const CANVAS_MIN_DISPLAY_ZOOM = 0.01;

function getCanvasMinZoom() {
    const base = (CanvasState.baseZoom && CanvasState.baseZoom > 0) ? CanvasState.baseZoom : CANVAS_BASE_ZOOM_DEFAULT;
    // 获取用户配置的缩放下限 (默认 10%)
    const userLimitPercent = getCanvasMinZoomLimit();
    const userLimit = userLimitPercent / 100;

    // 保底避免 0，且保证显示至少 1% 或用户设定的下限
    return Math.max(0.0001, base * Math.max(CANVAS_MIN_DISPLAY_ZOOM, userLimit));
}

function clampCanvasZoom(zoom) {
    const z = (typeof zoom === 'number' && isFinite(zoom)) ? zoom : 1;
    return Math.max(getCanvasMinZoom(), Math.min(3, z));
}

// 简易本地存储封装（仅用于滚动位置）
// 全局 Popover 状态管理 (防止穿透交互)
function updateCanvasPopoverState(isActive) {
    if (isActive) {
        document.body.classList.add('canvas-popover-active');
    } else {
        // 延时一帧检查，确保 DOM 状态已更新
        requestAnimationFrame(() => {
            const hasOpen = document.querySelector('.md-format-popover.open, .temp-color-popover.open, .md-color-popover.open, .md-delete-options-popover.open, .marker-dropdown-menu.open, .desc-clear-confirm-popover, .desc-height-settings-popover, .canvas-sidepanel-popover');
            if (!hasOpen) {
                document.body.classList.remove('canvas-popover-active');
            }
        });
    }
}

const DESC_CLEAR_CONFIRM_POPOVER_ID = 'descClearConfirmPopover';
const DESC_HEIGHT_SETTINGS_POPOVER_ID = 'descHeightSettingsPopover';
const CANVAS_SIDE_PANEL_POPOVER_ID = 'canvasSidePanelPopover';

function __showDescClearConfirmPopover(anchorEl, options = {}) {
    if (!anchorEl) return;
    const existing = document.getElementById(DESC_CLEAR_CONFIRM_POPOVER_ID);
    if (existing) existing.remove();

    const lang = typeof currentLang !== 'undefined' ? currentLang : 'zh';
    const isEn = lang === 'en' || lang === 'en_US' || lang === 'en-GB' || String(lang).toLowerCase().startsWith('en');
    const title = options.title || (isEn ? 'Clear this description?' : '确认清空说明？');
    const confirmLabel = options.confirmLabel || (isEn ? 'Clear' : '清空');
    const cancelLabel = options.cancelLabel || (isEn ? 'Cancel' : '取消');

    const pop = document.createElement('div');
    pop.id = DESC_CLEAR_CONFIRM_POPOVER_ID;
    pop.className = 'desc-clear-confirm-popover';
    pop.innerHTML = `
        <div class="desc-clear-confirm-title">${title}</div>
        <div class="desc-clear-confirm-actions">
            <button class="desc-clear-confirm-btn cancel" type="button">${cancelLabel}</button>
            <button class="desc-clear-confirm-btn confirm" type="button">${confirmLabel}</button>
        </div>
    `;

    document.body.appendChild(pop);

    const rect = anchorEl.getBoundingClientRect();
    const popRect = pop.getBoundingClientRect();
    let left = rect.left + rect.width / 2;
    let top = rect.bottom + 8;
    if (top + popRect.height > window.innerHeight - 8) {
        top = rect.top - popRect.height - 8;
    }
    const minLeft = 8 + popRect.width / 2;
    const maxLeft = window.innerWidth - 8 - popRect.width / 2;
    left = Math.min(maxLeft, Math.max(minLeft, left));
    pop.style.left = left + 'px';
    pop.style.top = top + 'px';

    updateCanvasPopoverState(true);

    const cleanup = () => {
        try { pop.remove(); } catch (_) { }
        updateCanvasPopoverState(false);
        document.removeEventListener('mousedown', onDocDown, true);
        document.removeEventListener('keydown', onKeyDown, true);
    };

    const onConfirm = () => {
        cleanup();
        if (typeof options.onConfirm === 'function') options.onConfirm();
    };

    const onCancel = () => {
        cleanup();
        if (typeof options.onCancel === 'function') options.onCancel();
    };

    const cancelBtn = pop.querySelector('.desc-clear-confirm-btn.cancel');
    const confirmBtn = pop.querySelector('.desc-clear-confirm-btn.confirm');
    if (cancelBtn) cancelBtn.addEventListener('click', (e) => { e.preventDefault(); e.stopPropagation(); onCancel(); });
    if (confirmBtn) confirmBtn.addEventListener('click', (e) => { e.preventDefault(); e.stopPropagation(); onConfirm(); });

    const onDocDown = (e) => {
        if (!pop.contains(e.target) && e.target !== anchorEl && !anchorEl.contains(e.target)) {
            cleanup();
        }
    };
    const onKeyDown = (e) => {
        if (e.key === 'Escape') cleanup();
    };

    setTimeout(() => {
        document.addEventListener('mousedown', onDocDown, true);
        document.addEventListener('keydown', onKeyDown, true);
    }, 0);
}

function __showDescHeightSettingsPopover(anchorEl, options = {}) {
    if (!anchorEl) return;
    const existing = document.getElementById(DESC_HEIGHT_SETTINGS_POPOVER_ID);
    if (existing) {
        const prevAnchorId = existing.dataset.anchorId || '';
        const nextAnchorId = anchorEl.dataset.descHeightAnchorId || '';
        if (prevAnchorId && nextAnchorId && prevAnchorId === nextAnchorId) {
            if (typeof existing.__cleanup === 'function') existing.__cleanup();
            else existing.remove();
            return;
        }
        if (typeof existing.__cleanup === 'function') existing.__cleanup();
        else existing.remove();
    }

    const lang = typeof currentLang !== 'undefined' ? currentLang : 'zh';
    const isEn = lang === 'en' || lang === 'en_US' || lang === 'en-GB' || String(lang).toLowerCase().startsWith('en');
    const title = options.title || (isEn ? 'Height settings' : '高度设置');
    const displayLabel = options.displayLabel || (isEn ? 'Display' : '显示');
    const editLabel = options.editLabel || (isEn ? 'Edit' : '编辑');
    const rowsModeLabel = options.rowsModeLabel || (isEn ? 'Rows' : '限制行数');
    const fullLabel = options.fullLabel || (isEn ? 'Full' : '完整');
    const rowsLabel = options.rowsLabel || (isEn ? 'Rows' : '行');

    const defaults = options.defaults || {};
    const defaultDisplayRows = Number.isFinite(defaults.displayRows) ? defaults.displayRows : 4;
    const defaultEditRows = Number.isFinite(defaults.editRows) ? defaults.editRows : 5;

    const getSettings = typeof options.getSettings === 'function'
        ? options.getSettings
        : () => ({ displayMode: 'rows', displayRows: defaultDisplayRows, editMode: 'full', editRows: defaultEditRows });

    let settings = getSettings() || {};
    const normalizeMode = (mode) => {
        if (mode === 'full') return 'full';
        if (mode === 'rows' || mode === 'fixed') return 'rows';
        return null;
    };
    settings = {
        displayMode: normalizeMode(settings.displayMode) || 'rows',
        displayRows: Number.isFinite(settings.displayRows) ? settings.displayRows : defaultDisplayRows,
        editMode: normalizeMode(settings.editMode) || 'full',
        editRows: Number.isFinite(settings.editRows) ? settings.editRows : defaultEditRows
    };

    const pop = document.createElement('div');
    pop.id = DESC_HEIGHT_SETTINGS_POPOVER_ID;
    pop.className = 'desc-height-settings-popover';
    pop.dataset.anchorId = anchorEl.dataset.descHeightAnchorId || `${Date.now()}-${Math.random()}`;
    anchorEl.dataset.descHeightAnchorId = pop.dataset.anchorId;
    pop.innerHTML = `
        <div class="desc-height-settings-title">${title}</div>
        <div class="desc-height-settings-row" data-scope="display">
            <div class="desc-height-settings-label">${displayLabel}</div>
            <div class="desc-height-settings-actions">
                <button type="button" class="desc-height-settings-btn" data-mode="full">${fullLabel}</button>
                <button type="button" class="desc-height-settings-btn" data-mode="rows">${rowsModeLabel}</button>
                <div class="desc-height-settings-input-wrap">
                    <input class="desc-height-settings-input" data-input="display" type="number" min="1" max="20" step="1" />
                    <span class="desc-height-settings-unit">${rowsLabel}</span>
                </div>
            </div>
        </div>
        <div class="desc-height-settings-row" data-scope="edit">
            <div class="desc-height-settings-label">${editLabel}</div>
            <div class="desc-height-settings-actions">
                <button type="button" class="desc-height-settings-btn" data-mode="full">${fullLabel}</button>
                <button type="button" class="desc-height-settings-btn" data-mode="rows">${rowsModeLabel}</button>
                <div class="desc-height-settings-input-wrap">
                    <input class="desc-height-settings-input" data-input="edit" type="number" min="1" max="20" step="1" />
                    <span class="desc-height-settings-unit">${rowsLabel}</span>
                </div>
            </div>
        </div>
    `;

    document.body.appendChild(pop);

    const rect = anchorEl.getBoundingClientRect();
    const popRect = pop.getBoundingClientRect();
    let left = rect.left + rect.width / 2;
    let top = rect.bottom + 8;
    if (top + popRect.height > window.innerHeight - 8) {
        top = rect.top - popRect.height - 8;
    }
    const minLeft = 8 + popRect.width / 2;
    const maxLeft = window.innerWidth - 8 - popRect.width / 2;
    left = Math.min(maxLeft, Math.max(minLeft, left));
    pop.style.left = left + 'px';
    pop.style.top = top + 'px';

    anchorEl.classList.add('active');
    anchorEl.setAttribute('aria-expanded', 'true');
    updateCanvasPopoverState(true);

    const normalizeRows = (value, fallback) => {
        const num = parseInt(value, 10);
        return Number.isFinite(num) && num > 0 ? num : fallback;
    };

    const applySettings = (next) => {
        settings = {
            displayMode: normalizeMode(next.displayMode || settings.displayMode),
            displayRows: Number.isFinite(next.displayRows) ? next.displayRows : settings.displayRows,
            editMode: normalizeMode(next.editMode || settings.editMode),
            editRows: Number.isFinite(next.editRows) ? next.editRows : settings.editRows
        };
        if (typeof options.onChange === 'function') options.onChange(settings);
        render();
    };

    const render = () => {
        const displayGroup = pop.querySelector('.desc-height-settings-row[data-scope="display"]');
        const editGroup = pop.querySelector('.desc-height-settings-row[data-scope="edit"]');
        const updateGroup = (groupEl, mode, rows) => {
            if (!groupEl) return;
            const buttons = groupEl.querySelectorAll('.desc-height-settings-btn');
            buttons.forEach(btn => {
                btn.classList.toggle('active', btn.dataset.mode === mode);
            });
            const input = groupEl.querySelector('.desc-height-settings-input');
            if (input) {
                input.value = rows;
                input.disabled = mode !== 'rows';
                const wrap = input.closest('.desc-height-settings-input-wrap');
                if (wrap) wrap.classList.toggle('disabled', mode !== 'rows');
            }
        };
        updateGroup(displayGroup, settings.displayMode, settings.displayRows);
        updateGroup(editGroup, settings.editMode, settings.editRows);
    };

    const handleModeClick = (scope, mode) => {
        if (scope === 'display') {
            let rows = settings.displayRows;
            if (mode === 'rows') rows = normalizeRows(settings.displayRows, defaultDisplayRows);
            applySettings({ displayMode: mode, displayRows: rows });
        } else {
            let rows = settings.editRows;
            if (mode === 'rows') rows = normalizeRows(settings.editRows, defaultEditRows);
            applySettings({ editMode: mode, editRows: rows });
        }
    };

    pop.addEventListener('click', (e) => {
        const btn = e.target.closest('.desc-height-settings-btn');
        if (!btn) return;
        const group = btn.closest('.desc-height-settings-row');
        if (!group) return;
        const scope = group.dataset.scope;
        const mode = btn.dataset.mode;
        handleModeClick(scope, mode);
    });

    pop.addEventListener('input', (e) => {
        const input = e.target.closest('.desc-height-settings-input');
        if (!input) return;
        const scope = input.dataset.input;
        if (scope === 'display') {
            const value = normalizeRows(input.value, defaultDisplayRows);
            applySettings({ displayMode: 'rows', displayRows: value });
        } else {
            const value = normalizeRows(input.value, defaultEditRows);
            applySettings({ editMode: 'rows', editRows: value });
        }
    });

    render();


    const cleanup = () => {
        try { pop.remove(); } catch (_) { }
        anchorEl.classList.remove('active');
        anchorEl.setAttribute('aria-expanded', 'false');
        updateCanvasPopoverState(false);
        document.removeEventListener('mousedown', onDocDown, true);
        document.removeEventListener('keydown', onKeyDown, true);
        if (typeof options.onClose === 'function') options.onClose();
    };

    pop.__cleanup = cleanup;

    const onDocDown = (e) => {
        if (!pop.contains(e.target) && e.target !== anchorEl && !anchorEl.contains(e.target)) {
            cleanup();
        }
    };
    const onKeyDown = (e) => {
        if (e.key === 'Escape') cleanup();
    };

    setTimeout(() => {
        document.addEventListener('mousedown', onDocDown, true);
        document.addEventListener('keydown', onKeyDown, true);
    }, 0);
}

function __positionCanvasSidePanelPopover(pop, anchorEl, side) {
    if (!pop || !anchorEl) return;
    const rect = anchorEl.getBoundingClientRect();
    const popRect = pop.getBoundingClientRect();
    let left = rect.left + rect.width / 2 - popRect.width / 2;
    if (side === 'left') left = rect.left;
    if (side === 'right') left = rect.right - popRect.width;
    const minLeft = 8;
    const maxLeft = window.innerWidth - 8 - popRect.width;
    left = Math.min(maxLeft, Math.max(minLeft, left));
    let top = rect.bottom + 8;
    if (top + popRect.height > window.innerHeight - 8) {
        top = rect.top - popRect.height - 8;
    }
    pop.style.left = left + 'px';
    pop.style.top = top + 'px';
}

async function __getSidePanelLayout() {
    try {
        if (chrome && chrome.sidePanel && typeof chrome.sidePanel.getLayout === 'function') {
            try {
                const maybePromise = chrome.sidePanel.getLayout();
                if (maybePromise && typeof maybePromise.then === 'function') {
                    return await maybePromise;
                }
            } catch (_) { }
            return await new Promise((resolve) => {
                try {
                    chrome.sidePanel.getLayout((layout) => resolve(layout));
                } catch (_) {
                    resolve(null);
                }
            });
        }
    } catch (_) { }
    return null;
}

function __getSidePanelSettingsSearchMeta() {
    const lang = (typeof currentLang !== 'undefined' && currentLang)
        ? currentLang
        : (navigator.language || '');
    const langLower = String(lang).toLowerCase();
    const isZh = langLower.startsWith('zh');
    const keyword = isZh ? '侧边栏' : 'side panel';
    const keywordAlt = isZh ? 'side panel' : '侧边栏';
    return {
        url: 'chrome://settings/?search=' + encodeURIComponent(keyword),
        keyword,
        keywordAlt,
        isZh,
        browser: 'chrome'
    };
}

function __showCanvasSidePanelPopover(anchorEl) {
    if (!anchorEl) return;
    const existing = document.getElementById(CANVAS_SIDE_PANEL_POPOVER_ID);
    if (existing) existing.remove();

    const lang = typeof currentLang !== 'undefined' ? currentLang : 'zh';
    const isEn = lang === 'en' || lang === 'en_US' || lang === 'en-GB' || String(lang).toLowerCase().startsWith('en');
    const title = isEn ? 'Side panel settings' : '侧边栏管理';
    const positionLabel = isEn ? 'Side panel position' : '侧边栏位置';
    const detectingText = isEn ? 'Detecting...' : '检测中...';
    const unknownText = isEn ? 'Unknown (open settings)' : '未知（打开设置查看）';
    const leftText = isEn ? 'Left' : '左侧';
    const rightText = isEn ? 'Right' : '右侧';
    const openSettingsText = isEn ? 'Browser settings' : '浏览器设置';
    const hintText = '';

    const pop = document.createElement('div');
    pop.id = CANVAS_SIDE_PANEL_POPOVER_ID;
    pop.className = 'canvas-sidepanel-popover';
    pop.innerHTML = `
        <div class="canvas-sidepanel-row">
            <span class="canvas-sidepanel-label">${positionLabel}</span>
            <span class="canvas-sidepanel-value" id="canvasSidePanelPositionValue">${detectingText}</span>
        </div>
        <div class="canvas-sidepanel-actions">
            <button class="canvas-sidepanel-btn" id="canvasSidePanelOpenSettingsBtn" type="button">${openSettingsText}</button>
        </div>
        <div class="canvas-sidepanel-hint">${hintText}</div>
    `;

    document.body.appendChild(pop);
    __positionCanvasSidePanelPopover(pop, anchorEl, null);
    updateCanvasPopoverState(true);

    const positionEl = pop.querySelector('#canvasSidePanelPositionValue');
    __getSidePanelLayout().then((layout) => {
        const side = layout && layout.side ? String(layout.side) : '';
        if (positionEl) {
            if (side === 'left') positionEl.textContent = leftText;
            else if (side === 'right') positionEl.textContent = rightText;
            else positionEl.textContent = unknownText;
        }
        pop.dataset.side = side || 'unknown';
        __positionCanvasSidePanelPopover(pop, anchorEl, side);
    });

    const openBtn = pop.querySelector('#canvasSidePanelOpenSettingsBtn');
    if (openBtn) {
        openBtn.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            try {
                if (chrome && chrome.tabs && typeof chrome.tabs.create === 'function') {
                    const meta = __getSidePanelSettingsSearchMeta();
                    chrome.tabs.create({ url: meta.url });
                }
            } catch (_) { }
        });
    }

    const cleanup = () => {
        try { pop.remove(); } catch (_) { }
        updateCanvasPopoverState(false);
        document.removeEventListener('mousedown', onDocDown, true);
        document.removeEventListener('keydown', onKeyDown, true);
    };

    const onDocDown = (e) => {
        if (!pop.contains(e.target) && e.target !== anchorEl && !anchorEl.contains(e.target)) {
            cleanup();
        }
    };
    const onKeyDown = (e) => {
        if (e.key === 'Escape') cleanup();
    };

    setTimeout(() => {
        document.addEventListener('mousedown', onDocDown, true);
        document.addEventListener('keydown', onKeyDown, true);
    }, 0);
}

function __setupDescAutoScroll(editorEl, isEditing) {
    if (!editorEl || editorEl.__descAutoScrollBound) return;
    editorEl.__descAutoScrollBound = true;

    let rafId = null;
    let lastEvent = null;
    let active = false;

    const tick = () => {
        if (!active) {
            rafId = null;
            return;
        }
        if (typeof isEditing === 'function' && !isEditing()) {
            active = false;
            rafId = null;
            return;
        }
        if (!lastEvent) {
            rafId = requestAnimationFrame(tick);
            return;
        }
        if (editorEl.scrollHeight <= editorEl.clientHeight) {
            rafId = requestAnimationFrame(tick);
            return;
        }
        const rect = editorEl.getBoundingClientRect();
        const baseZone = Math.max(48, Math.min(Math.round(rect.height * 0.18), 140));
        const speed = 16;
        let delta = 0;
        if (lastEvent.clientY > rect.top && lastEvent.clientY < rect.top + baseZone) {
            delta = -speed * ((rect.top + baseZone - lastEvent.clientY) / baseZone);
        } else if (lastEvent.clientY < rect.bottom && lastEvent.clientY > rect.bottom - baseZone) {
            delta = speed * ((lastEvent.clientY - (rect.bottom - baseZone)) / baseZone);
        }
        if (delta !== 0) editorEl.scrollTop += delta;
        rafId = requestAnimationFrame(tick);
    };

    const start = (e) => {
        if (typeof isEditing === 'function' && !isEditing()) return;
        lastEvent = e;
        if (!active) {
            active = true;
            rafId = requestAnimationFrame(tick);
        }
    };

    const move = (e) => {
        if (typeof isEditing === 'function' && !isEditing()) return;
        lastEvent = e;
        if (!active) {
            active = true;
            rafId = requestAnimationFrame(tick);
        }
    };

    const stop = () => {
        active = false;
        lastEvent = null;
        if (rafId) {
            cancelAnimationFrame(rafId);
            rafId = null;
        }
    };

    editorEl.addEventListener('mouseenter', start);
    editorEl.addEventListener('mousemove', move);
    editorEl.addEventListener('mouseleave', stop);
    editorEl.addEventListener('blur', stop);
}


// 阻止 Canvas 事件冒泡 (防止 UI 内部拖动触发父级 Drag/Resize)
function preventCanvasEventsPropagation(element) {
    if (!element) return;
    ['mousedown', 'dblclick', 'dragstart'].forEach(evt => {
        element.addEventListener(evt, (e) => e.stopPropagation());
    });
}

function __readJSON(key, fallback = null) {
    try {
        const v = localStorage.getItem(key);
        if (!v) return fallback;
        return JSON.parse(v);
    } catch (_) { return fallback; }
}

// 统一写入入口（共享状态）：
// - 新增持久化状态时，优先使用本方法，避免散落 setItem 难维护。
// - 约束：除本入口外，业务代码不要直接调用 localStorage.setItem。
function saveSharedState(key, value, options = {}) {
    if (typeof key !== 'string' || !key) return false;
    const asJSON = !(options && options.asJSON === false);
    try {
        const payload = asJSON ? JSON.stringify(value) : String(value);
        localStorage.setItem(key, payload);
        return true;
    } catch (_) {
        return false;
    }
}

// 统一写入入口（视图分区状态）：
// - `kind==='camera'` 使用相机命名空间；
// - 其他 kind 使用 canvas:view:v1:<kind>:<partition>:<baseKey>。
function saveViewState(kind, baseKey, value, options = {}) {
    if (typeof kind !== 'string' || !kind || typeof baseKey !== 'string' || !baseKey) return false;

    const partitionKey = (options && typeof options.partitionKey === 'string' && options.partitionKey)
        ? options.partitionKey
        : __getCanvasViewPartitionKey();

    const storageKey = (kind === 'camera')
        ? __buildCanvasCameraStorageKey(partitionKey, baseKey)
        : __buildCanvasPartitionedViewStateKey(kind, baseKey, partitionKey);

    if (!storageKey) return false;
    return saveSharedState(storageKey, value, { asJSON: !(options && options.asJSON === false) });
}

function __writeJSON(key, obj) {
    saveSharedState(key, obj);
}

function __readCanvasStorageSchemaVersion() {
    try {
        const raw = localStorage.getItem(CANVAS_STORAGE_SCHEMA_VERSION_KEY);
        if (!raw) return 0;
        const parsed = parseInt(raw, 10);
        return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;
    } catch (_) {
        return 0;
    }
}

function __writeCanvasStorageSchemaVersion(version) {
    try {
        const value = parseInt(version, 10);
        if (!Number.isFinite(value) || value <= 0) return;
        saveSharedState(CANVAS_STORAGE_SCHEMA_VERSION_KEY, String(value), { asJSON: false });
    } catch (_) { }
}

function __ensureCanvasStorageSchema() {
    const currentVersion = __readCanvasStorageSchemaVersion();
    if (currentVersion >= CANVAS_STORAGE_SCHEMA_VERSION) return;

    __writeCanvasStorageSchemaVersion(CANVAS_STORAGE_SCHEMA_VERSION);

    try {
        console.log(`[Canvas] Storage schema upgraded to v${CANVAS_STORAGE_SCHEMA_VERSION}.`);
    } catch (_) { }
}

function __buildCanvasPartitionedViewStateKey(kind, baseKey, partitionKey = null) {
    if (!kind || !baseKey) return baseKey;
    const partition = partitionKey || __getCanvasViewPartitionKey();
    return `${CANVAS_VIEW_STATE_STORAGE_NS}:${kind}:${partition}:${baseKey}`;
}

function __readPartitionedViewJSON(key, fallback = null) {
    const data = __readJSON(key, null);
    if (data !== null) return data;
    return fallback;
}

function __removeCanvasPartitionedViewStateKey(kind, baseKey) {
    if (!kind || !baseKey) return;
    try { localStorage.removeItem(__buildCanvasPartitionedViewStateKey(kind, baseKey, 'page')); } catch (_) { }
    try { localStorage.removeItem(__buildCanvasPartitionedViewStateKey(kind, baseKey, 'sidepanel')); } catch (_) { }
    try { localStorage.removeItem(baseKey); } catch (_) { }
}

function __normalizeDescHeightSettings(raw, defaults) {
    const normalizeMode = (mode) => {
        if (mode === 'full') return 'full';
        if (mode === 'rows' || mode === 'fixed') return 'rows';
        return null;
    };
    const normalizeRows = (value, fallback) => {
        const num = parseInt(value, 10);
        return Number.isFinite(num) && num > 0 ? num : fallback;
    };
    const input = raw || {};
    return {
        displayMode: normalizeMode(input.displayMode) || defaults.displayMode,
        displayRows: normalizeRows(input.displayRows, defaults.displayRows),
        editMode: normalizeMode(input.editMode) || defaults.editMode,
        editRows: normalizeRows(input.editRows, defaults.editRows)
    };
}

function __readDescHeightSettings(key, defaults, fallback = null) {
    const stored = __readJSON(key, null);
    if (stored) return __normalizeDescHeightSettings(stored, defaults);
    if (fallback) return __normalizeDescHeightSettings(fallback, defaults);
    return __normalizeDescHeightSettings({}, defaults);
}

function __writeDescHeightSettings(key, settings) {
    __writeJSON(key, settings);
}

// 多次尝试恢复滚动，避免首次布局或字体加载导致的覆盖
function __restoreScroll(el, key, options = {}) {
    if (!el || !key) return;
    const kind = options && typeof options.kind === 'string' ? options.kind : null;
    const data = __readPartitionedViewJSON(key, null, kind);
    const apply = () => {
        if (!data) return;
        if (typeof data.top === 'number') el.scrollTop = data.top || 0;
        if (typeof data.left === 'number') el.scrollLeft = data.left || 0;
    };
    apply();
    requestAnimationFrame(() => {
        apply();
        setTimeout(apply, 10);
        setTimeout(apply, 50);
        setTimeout(apply, 100);
    });
}

let panSaveTimeout = null;
const CANVAS_SCROLL_MARGIN = 120;
const CANVAS_SCROLL_EXTRA_SPACE = 2000; // 允许滚动到内容外2000px的空白区域
let suppressScrollSync = false;
let zoomSaveTimeout = null;
let scrollbarPreloadSaveTimeout = null;
let zoomUpdateFrame = null;
let pendingZoomRequest = null;
// 性能优化：滚动更新去抖（RAF）
let scrollUpdateFrame = null;
let pendingScrollRequest = null;
const scrollbarHoverState = new WeakMap();

// 性能优化：滚动条更新去抖
let scrollbarUpdateFrame = null;
let scrollbarUpdatePending = false;
let boundsUpdateFrame = null;
let boundsUpdatePending = false;

// 性能优化：滚动/缩放停止检测
let scrollStopTimer = null;
let isScrolling = false;
const SCROLL_STOP_DELAY = 150; // 滚动停止后延迟加载时间

// 性能优化：缓存 DOM 元素引用，避免重复查询
let cachedCanvasContainer = null;
let cachedCanvasContent = null;
let cachedCanvasGridLayer = null;
let cachedCanvasScaleVarsContainer = null;
let cachedCanvasScaleVarsValue = null;
let cachedCanvasGridTransform = null;

// 性能优化：休眠管理节流
let dormancyUpdateTimer = null;
let dormancyUpdatePending = false;
let lastDormancyCheckTime = 0; // [Fix] 用于滚动过程中的节流检查
let lastResizeTime = 0; // [Fix] 用于防止Resize过程中的闪烁
let canvasBlockDormancyUnloadTimer = null;
// 防止重复绑定：临时栏目书签链接点击处理器
let tempLinkClickHandler = null;

function getCachedContainer() {
    if (!cachedCanvasContainer) {
        cachedCanvasContainer = document.querySelector('.canvas-main-container');
    }
    return cachedCanvasContainer;
}

function getCachedContent() {
    if (!cachedCanvasContent) {
        cachedCanvasContent = document.getElementById('canvasContent');
    }
    return cachedCanvasContent;
}

function getCachedGridLayer() {
    if (!cachedCanvasGridLayer) {
        cachedCanvasGridLayer = document.getElementById('canvasGridLayer');
    }
    return cachedCanvasGridLayer;
}

function __modWrapPx(value, period) {
    if (!isFinite(value)) return 0;
    if (!isFinite(period) || period <= 0) return 0;
    let r = value % period;
    const half = period / 2;
    if (r > half) r -= period;
    if (r < -half) r += period;
    return r;
}

function updateCanvasGridLayerTransform(panX, panY, scale, force = false) {
    const grid = getCachedGridLayer();
    if (!grid) return;

    if (!force) {
        const workspace = document.getElementById('canvasWorkspace');
        if (workspace && workspace.classList.contains('is-zooming')) return;
    }

    const pxX = (typeof panX === 'number' && isFinite(panX)) ? panX : 0;
    const pxY = (typeof panY === 'number' && isFinite(panY)) ? panY : 0;
    const z = (typeof scale === 'number' && isFinite(scale) && scale > 0) ? scale : 1;

    // 与 CSS background-size 保持一致：gridSpacingPx = zoom * 100px
    const gridSpacingPx = Math.max(0.25, z * 100);
    // [Fix] 解决网格抖动问题：使用 round 避免浮点数精度导致的微小位移
    // 当 zoom 变化时，模运算的结果会发生跳变，这是导致网格“游走”的原因
    // 强制只在缩放结束时更新 (force=true)，缩放中 (force=false) 直接不计算，这里只负责最终定位
    const x = __modWrapPx(pxX, gridSpacingPx);
    const y = __modWrapPx(pxY, gridSpacingPx);
    const next = `translate3d(${x}px, ${y}px, 0)`;

    // if (!force && cachedCanvasGridTransform === next) return; // 移除 cache check 对 force 的限制
    if (!force && cachedCanvasGridTransform === next) return;

    cachedCanvasGridTransform = next;
    try { grid.style.transform = next; } catch (_) { }
}

// =============================================================================
// Ctrl 专属栏目操作（蒙版 + 拖动/尺寸调整入口）
// =============================================================================

function isSectionCtrlModeEvent(e) {
    return !!(CanvasState.sectionCtrlMode && CanvasState.sectionCtrlMode.active) || (!!e && (isCustomCtrlKeyPressed(e) || e.metaKey));
}

function resolveSectionMeta(element) {
    if (!element) return null;
    if (element.id === 'permanentSection' || (element.classList && element.classList.contains('permanent-bookmark-section'))) {
        return {
            type: 'permanent-section',
            data: null,
            x: parseFloat(element.style.left) || 0,
            y: parseFloat(element.style.top) || 0,
            locked: element.dataset && element.dataset.locked === 'true',
            isEditing: false
        };
    }

    if (element.classList.contains('md-canvas-node')) {
        const data = Array.isArray(CanvasState.mdNodes) ? CanvasState.mdNodes.find(n => n.id === element.id) : null;
        if (!data) return null;
        return {
            type: 'md-node',
            data,
            x: typeof data.x === 'number' ? data.x : (parseFloat(element.style.left) || 0),
            y: typeof data.y === 'number' ? data.y : (parseFloat(element.style.top) || 0),
            locked: !!data.locked,
            isEditing: !!data.isEditing
        };
    }

    if (element.classList.contains('temp-canvas-node')) {
        const data = CanvasState.tempSections.find(n => n.id === element.id);
        if (!data) return null;
        return {
            type: 'temp-node',
            data,
            x: typeof data.x === 'number' ? data.x : (parseFloat(element.style.left) || 0),
            y: typeof data.y === 'number' ? data.y : (parseFloat(element.style.top) || 0),
            locked: false,
            isEditing: false
        };
    }

    return null;
}

function registerSectionCtrlOverlay(element) {
    if (!element) return null;
    let overlay = element.querySelector('.canvas-section-ctrl-overlay');
    if (!overlay) {
        overlay = document.createElement('div');
        overlay.className = 'canvas-section-ctrl-overlay';
        overlay.addEventListener('mousedown', handleCtrlOverlayMouseDown, true);
        overlay.addEventListener('contextmenu', (e) => {
            if (isSectionCtrlModeEvent(e)) {
                e.preventDefault();
                e.stopPropagation();
            }
        });
        overlay.addEventListener('wheel', (e) => {
            // 允许 Ctrl+滚轮 进行画布缩放，不阻止
            if (isCustomCtrlKeyPressed(e) || e.metaKey) {
                return;
            }
            // 其他情况下，如果在Ctrl模式中，阻止默认滚动
            if (CanvasState.sectionCtrlMode && CanvasState.sectionCtrlMode.active) {
                e.preventDefault();
                e.stopPropagation();
            }
        }, { passive: false });
        element.appendChild(overlay);
    }

    const isPermanentSection = !!(element.classList && element.classList.contains('permanent-bookmark-section'));
    overlay.dataset.sectionId = isPermanentSection
        ? (__getPermanentSectionCopyId(element) || element.id || '')
        : (element.id || '');
    overlay.dataset.sectionType = isPermanentSection
        ? 'permanent-section'
        : (element.classList.contains('md-canvas-node') ? 'md-node' : 'temp-node');
    overlay.classList.toggle('active', !!(CanvasState.sectionCtrlMode && CanvasState.sectionCtrlMode.active));

    if (CanvasState.sectionCtrlMode && CanvasState.sectionCtrlMode.resize && CanvasState.sectionCtrlMode.resize.element === element) {
        overlay.classList.add('ctrl-resize');
    } else {
        overlay.classList.remove('ctrl-resize');
    }

    return overlay;
}

function refreshSectionCtrlOverlays() {
    const canvasContent = document.getElementById('canvasContent');
    const scope = canvasContent || document;
    const nodes = scope.querySelectorAll('.temp-canvas-node, .md-canvas-node, .permanent-bookmark-section');
    nodes.forEach(el => registerSectionCtrlOverlay(el));
}

function setSectionCtrlModeActive(active) {
    const wasActive = !!(CanvasState.sectionCtrlMode && CanvasState.sectionCtrlMode.active);
    if (wasActive === active) return;
    CanvasState.sectionCtrlMode.active = active;
    if (!active) {
        endCtrlResize(false);
    }
    refreshSectionCtrlOverlays();
}

function startSectionDrag(element, event) {
    if (!isSectionCtrlModeEvent(event)) return false;
    if (!element || event.button !== 0) return false;
    if (CanvasState.sectionCtrlMode.resize && CanvasState.sectionCtrlMode.resize.active) return false;

    const meta = resolveSectionMeta(element);
    if (!meta || meta.locked || meta.isEditing) return false;

    CanvasState.dragState.isDragging = true;
    CanvasState.dragState.draggedElement = element;
    CanvasState.dragState.dragStartX = event.clientX;
    CanvasState.dragState.dragStartY = event.clientY;
    CanvasState.dragState.nodeStartX = meta.x;
    CanvasState.dragState.nodeStartY = meta.y;
    CanvasState.dragState.dragSource = meta.type === 'permanent-section' ? 'permanent-section' : 'temp-node';
    CanvasState.dragState.lastClientX = event.clientX;
    CanvasState.dragState.lastClientY = event.clientY;
    CanvasState.dragState.hasMoved = false;
    CanvasState.dragState.meta = { ctrlOverlay: !!CanvasState.sectionCtrlMode.active };
    CanvasState.dragState.wheelScrollEnabled = true;

    element.classList.add('dragging');
    element.style.transition = 'none';

    if (meta.type === 'permanent-section') {
        element.style.transform = 'none';
    }

    CanvasState.dragState.childElements = [];
    // import-container：拖动时只带走“已绑定为组内成员”的节点（不做重叠吸附）
    if (meta.data && meta.data.subtype === 'import-container') {
        try {
            __ensureImportContainerMembership(meta.data);
            CanvasState.dragState.childElements = __collectImportContainerChildElements(meta.data);
        } catch (_) {
            CanvasState.dragState.childElements = [];
        }
    }

    event.preventDefault();
    return true;
}

function __getRectOfSectionOrNode(obj, type) {
    if (!obj) return null;
    const x = Number(type === 'temp-section' ? obj.x : obj.x);
    const y = Number(type === 'temp-section' ? obj.y : obj.y);
    const w = Number(obj.width);
    const h = Number(obj.height);
    if (![x, y, w, h].every(v => typeof v === 'number' && isFinite(v))) return null;
    return { x, y, w, h };
}

function __rectsOverlap(a, b, margin = 0) {
    if (!a || !b) return false;
    const m = (typeof margin === 'number' && isFinite(margin)) ? margin : 0;
    return !(
        a.x + a.w + m <= b.x ||
        b.x + b.w + m <= a.x ||
        a.y + a.h + m <= b.y ||
        b.y + b.h + m <= a.y
    );
}

function __rectFullyInside(inner, outer, margin = 0) {
    if (!inner || !outer) return false;
    const m = (typeof margin === 'number' && isFinite(margin)) ? margin : 0;
    return (
        inner.x >= outer.x + m &&
        inner.y >= outer.y + m &&
        inner.x + inner.w <= outer.x + outer.w - m &&
        inner.y + inner.h <= outer.y + outer.h - m
    );
}

function __ensureImportContainerMembership(containerNode) {
    if (!containerNode || containerNode.subtype !== 'import-container') return;
    if (!containerNode.containedTempIds) containerNode.containedTempIds = [];
    if (!containerNode.containedMdIds) containerNode.containedMdIds = [];
    if (containerNode._membershipInitialized) return;

    // 若当前与其它组框重叠，避免“误吸附”迁移：保持空成员，后续由用户手动拖入建立关系
    const selfRect = __getRectOfSectionOrNode(containerNode, 'md-node');
    if (!selfRect) {
        containerNode._membershipInitialized = true;
        return;
    }
    const otherContainers = Array.isArray(CanvasState.mdNodes)
        ? CanvasState.mdNodes.filter(n => n && n.id && n.id !== containerNode.id && n.subtype === 'import-container')
        : [];
    const overlapsOther = otherContainers.some((n) => {
        const r = __getRectOfSectionOrNode(n, 'md-node');
        return r ? __rectsOverlap(selfRect, r, 0) : false;
    });
    if (overlapsOther) {
        containerNode._membershipInitialized = true;
        return;
    }

    // 尝试一次性迁移：把“完全在框内”的节点作为初始成员（仅在不重叠的情况下）
    const zoom = (CanvasState.zoom && CanvasState.zoom > 0) ? CanvasState.zoom : 1;
    const margin = 12 / zoom;

    const tempIds = [];
    for (const s of (CanvasState.tempSections || [])) {
        if (!s || !s.id) continue;
        const r = __getRectOfSectionOrNode(s, 'temp-section');
        if (r && __rectFullyInside(r, selfRect, margin)) tempIds.push(s.id);
    }
    const mdIds = [];
    for (const n of (CanvasState.mdNodes || [])) {
        if (!n || !n.id) continue;
        if (n.id === containerNode.id) continue;
        if (n.subtype === 'import-container') continue; // 不自动把组框放进组框
        const r = __getRectOfSectionOrNode(n, 'md-node');
        if (r && __rectFullyInside(r, selfRect, margin)) mdIds.push(n.id);
    }

    containerNode.containedTempIds = Array.from(new Set([...(containerNode.containedTempIds || []), ...tempIds]));
    containerNode.containedMdIds = Array.from(new Set([...(containerNode.containedMdIds || []), ...mdIds]));
    containerNode._membershipInitialized = true;
    try { saveTempNodes(); } catch (_) { }
}

function __collectImportContainerChildElements(containerNode) {
    if (!containerNode || containerNode.subtype !== 'import-container') return [];
    __ensureImportContainerMembership(containerNode);
    const childElements = [];

    const tempIds = Array.isArray(containerNode.containedTempIds) ? containerNode.containedTempIds : [];
    tempIds.forEach((id) => {
        const sec = (CanvasState.tempSections || []).find(s => s && s.id === id);
        if (!sec) return;
        childElements.push({
            type: 'temp-section',
            data: sec,
            startX: Number(sec.x),
            startY: Number(sec.y),
            element: document.getElementById(sec.id)
        });
    });

    const mdIds = Array.isArray(containerNode.containedMdIds) ? containerNode.containedMdIds : [];
    mdIds.forEach((id) => {
        const n = (CanvasState.mdNodes || []).find(nn => nn && nn.id === id);
        if (!n) return;
        childElements.push({
            type: 'md-node',
            data: n,
            startX: Number(n.x),
            startY: Number(n.y),
            element: document.getElementById(n.id)
        });
    });

    childElements.forEach((child) => {
        if (child && child.element) {
            try { child.element.style.transition = 'none'; } catch (_) { }
        }
    });

    return childElements;
}

function __removeNodeFromAllImportContainers(nodeId) {
    if (!nodeId) return false;
    let changed = false;
    for (const c of (CanvasState.mdNodes || [])) {
        if (!c || c.subtype !== 'import-container') continue;
        if (Array.isArray(c.containedTempIds) && c.containedTempIds.includes(nodeId)) {
            c.containedTempIds = c.containedTempIds.filter(id => id !== nodeId);
            changed = true;
        }
        if (Array.isArray(c.containedMdIds) && c.containedMdIds.includes(nodeId)) {
            c.containedMdIds = c.containedMdIds.filter(id => id !== nodeId);
            changed = true;
        }
    }
    return changed;
}

function __addNodeToImportContainer(containerNode, nodeId, nodeType) {
    if (!containerNode || containerNode.subtype !== 'import-container') return false;
    if (!nodeId) return false;
    __ensureImportContainerMembership(containerNode);
    if (nodeType === 'temp-section') {
        containerNode.containedTempIds = Array.isArray(containerNode.containedTempIds) ? containerNode.containedTempIds : [];
        if (!containerNode.containedTempIds.includes(nodeId)) {
            containerNode.containedTempIds.push(nodeId);
            return true;
        }
        return false;
    }
    if (nodeType === 'md-node') {
        // 不允许组框进组框（降低误触/误吸附）
        const n = (CanvasState.mdNodes || []).find(nn => nn && nn.id === nodeId);
        if (n && n.subtype === 'import-container') return false;
        containerNode.containedMdIds = Array.isArray(containerNode.containedMdIds) ? containerNode.containedMdIds : [];
        if (!containerNode.containedMdIds.includes(nodeId)) {
            containerNode.containedMdIds.push(nodeId);
            return true;
        }
        return false;
    }
    return false;
}

function __updateImportContainerMembershipAfterMove(nodeId) {
    if (!nodeId) return;
    const temp = (CanvasState.tempSections || []).find(s => s && s.id === nodeId) || null;
    const md = (CanvasState.mdNodes || []).find(n => n && n.id === nodeId) || null;
    const nodeType = temp ? 'temp-section' : (md ? 'md-node' : null);
    if (!nodeType) return;
    if (md && md.subtype === 'import-container') return; // 组框本身不参与

    const nodeRect = __getRectOfSectionOrNode(temp || md, nodeType);
    if (!nodeRect) return;

    const zoom = (CanvasState.zoom && CanvasState.zoom > 0) ? CanvasState.zoom : 1;
    const margin = 12 / zoom;

    const containers = (CanvasState.mdNodes || []).filter(n => n && n.subtype === 'import-container');
    // 选择“最小能完全包含”的容器（更符合小放大、可嵌套的直觉）
    let target = null;
    let bestArea = Infinity;
    for (const c of containers) {
        if (!c || !c.id) continue;
        const r = __getRectOfSectionOrNode(c, 'md-node');
        if (!r) continue;
        if (!__rectFullyInside(nodeRect, r, margin)) continue;
        const area = r.w * r.h;
        if (area < bestArea) {
            bestArea = area;
            target = c;
        }
    }

    let changed = false;
    changed = __removeNodeFromAllImportContainers(nodeId) || changed;
    if (target) {
        changed = __addNodeToImportContainer(target, nodeId, nodeType) || changed;
    }
    if (changed) {
        try { saveTempNodes(); } catch (_) { }
    }
}

function __recomputeImportContainerMembershipForTempState(tempState) {
    if (!tempState || typeof tempState !== 'object') return;
    const tempSections = Array.isArray(tempState.sections) ? tempState.sections : [];
    const mdNodes = Array.isArray(tempState.mdNodes) ? tempState.mdNodes : [];
    const containers = mdNodes.filter(n => n && n.subtype === 'import-container');
    if (containers.length === 0) return;

    const margin = 12;

    const getRect = (obj) => {
        if (!obj) return null;
        const x = Number(obj.x);
        const y = Number(obj.y);
        const w = Number(obj.width);
        const h = Number(obj.height);
        if (![x, y, w, h].every(v => typeof v === 'number' && isFinite(v))) return null;
        return { x, y, w, h };
    };

    // Reset and mark initialized: membership is derived from geometry here (Obsidian .canvas has no explicit membership).
    containers.forEach((c) => {
        c.containedTempIds = [];
        c.containedMdIds = [];
        c._membershipInitialized = true;
    });

    const findSmallestContainer = (rect) => {
        let target = null;
        let bestArea = Infinity;
        for (const c of containers) {
            const cr = getRect(c);
            if (!cr) continue;
            if (!__rectFullyInside(rect, cr, margin)) continue;
            const area = cr.w * cr.h;
            if (area < bestArea) {
                bestArea = area;
                target = c;
            }
        }
        return target;
    };

    for (const s of tempSections) {
        if (!s || !s.id) continue;
        const r = getRect(s);
        if (!r) continue;
        const c = findSmallestContainer(r);
        if (c) {
            c.containedTempIds.push(s.id);
        }
    }

    for (const n of mdNodes) {
        if (!n || !n.id) continue;
        if (n.subtype === 'import-container') continue; // 不做组框进组框
        const r = getRect(n);
        if (!r) continue;
        const c = findSmallestContainer(r);
        if (c) {
            c.containedMdIds.push(n.id);
        }
    }
}

function startSectionResize(element, event) {
    if (!isSectionCtrlModeEvent(event)) return false;
    if (!element || event.button !== 2) return false;
    if (CanvasState.dragState && CanvasState.dragState.isDragging) return false;

    const meta = resolveSectionMeta(element);
    if (!meta || meta.locked || meta.isEditing) return false;

    const state = CanvasState.sectionCtrlMode.resize;
    state.active = true;
    state.element = element;
    state.type = meta.type === 'permanent-section' ? 'permanent-section' : 'temp-node';
    state.data = meta.data;
    state.startX = event.clientX;
    state.startY = event.clientY;
    state.startWidth = element.offsetWidth;
    state.startHeight = element.offsetHeight;
    state.startLeft = meta.x;
    state.startTop = meta.y;
    state.minWidth = meta.type === 'permanent-section' ? 300 : (meta.type === 'md-node' ? 180 : 200);
    state.minHeight = meta.type === 'permanent-section' ? 200 : (meta.type === 'md-node' ? 140 : 150);
    state.waitForSecondRightClick = true; // 第二次右键才结束

    element.classList.add('resizing');
    const overlay = registerSectionCtrlOverlay(element);
    if (overlay) overlay.classList.add('ctrl-resize');

    applyCtrlResize(event.clientX, event.clientY);

    event.preventDefault();
    event.stopPropagation();
    return true;
}

function applyCtrlResize(clientX, clientY) {
    const state = CanvasState.sectionCtrlMode.resize;
    if (!state || !state.active || !state.element) return;

    const deltaX = (clientX - state.startX) / (CanvasState.zoom || 1);
    const deltaY = (clientY - state.startY) / (CanvasState.zoom || 1);

    const newWidth = Math.max(state.minWidth, state.startWidth + deltaX);
    const newHeight = Math.max(state.minHeight, state.startHeight + deltaY);

    state.element.style.width = `${newWidth}px`;
    state.element.style.height = `${newHeight}px`;

    if (state.type === 'permanent-section') {
        // 固定左上角，宽高变化即可
    } else if (state.data) {
        state.data.width = newWidth;
        state.data.height = newHeight;
    }
}

function endCtrlResize(force) {
    const state = CanvasState.sectionCtrlMode.resize;
    if (!state || !state.active) return;

    if (!force) {
        if (state.type === 'permanent-section') {
            savePermanentSectionPosition(state.element);
        } else if (state.data) {
            saveTempNodes();
        }
        updateCanvasScrollBounds();
        updateScrollbarThumbs();
    }

    if (state.element) {
        state.element.classList.remove('resizing');
    }

    const overlay = state.element ? state.element.querySelector('.canvas-section-ctrl-overlay') : null;
    if (overlay) overlay.classList.remove('ctrl-resize');

    state.active = false;
    state.element = null;
    state.type = null;
    state.data = null;
    state.waitForSecondRightClick = false;
}

function handleCtrlOverlayMouseDown(e) {
    if (!isSectionCtrlModeEvent(e)) return;
    const host = e.currentTarget ? e.currentTarget.parentElement : null;
    if (!host) return;
    e.preventDefault();
    e.stopPropagation();

    const resizeState = CanvasState.sectionCtrlMode && CanvasState.sectionCtrlMode.resize;

    if (resizeState && resizeState.active && resizeState.waitForSecondRightClick && e.button === 2) {
        // 第二次右键点击，结束缩放
        endCtrlResize(false);
        return;
    }

    if (e.button === 0) {
        startSectionDrag(host, e);
    } else if (e.button === 2) {
        startSectionResize(host, e);
    }
}
