// [Special Temp 接入约定]
// 新增“特殊临时栏目”时，建议只做这一步：为 section.source 分配稳定值，并加入下面集合。
// 命中后会自动接入：
// - 外观尺寸：sizes.specialTemp
// - 外观颜色：colors.specialTemp
// - 颜色锁行为：与常规临时栏目共用同一套设置
// 兼容旧数据时，__isSpecialTempSection 仍会回退用 label 判定。
const SPECIAL_TEMP_SOURCE_SET = new Set(['browser-drop', 'search-result', 'batch', 'quick-add', 'file-import', 'import-html-bookmarks', 'import-json-bookmarks']);

function __isSpecialTempSection(section) {
    if (!section) return false;
    const sourceRaw = (typeof section.source === 'string') ? section.source.trim() : '';
    const source = sourceRaw.toLowerCase();
    if (source && SPECIAL_TEMP_SOURCE_SET.has(source)) return true;
    const labelRaw = (typeof section.label === 'string') ? section.label.trim() : '';
    if (!labelRaw) return false;
    if (labelRaw === '拖入' || labelRaw === '搜索' || labelRaw === '批量' || labelRaw === '添加' || labelRaw === '导入文件' || labelRaw === '导入') return true;
    const label = labelRaw.toLowerCase();
    return label === 'drop' || label === 'search' || label === 'batch' || label === 'add' || label === 'import file' || label === 'import';
}

function __isTempSectionColorLocked(section) {
    if (!section) return true;
    return !!section.colorLocked;
}

function __isTempSectionManuallyLocked(section) {
    return !!(section && section.colorLocked === true);
}

function __getDefaultTempColorLockedState() {
    return !isTempColorFollowEnabled();
}

function __applyTempColorLockButtonState(lockBtn, section) {
    if (!lockBtn || !section) return;
    const locked = __isTempSectionColorLocked(section);
    const isEn = typeof currentLang !== 'undefined' && (currentLang === 'en' || currentLang === 'en_US' || currentLang === 'en-GB' || String(currentLang).toLowerCase().startsWith('en'));
    const lockLabel = isEn ? 'Lock color' : '锁定颜色';
    const unlockLabel = isEn ? 'Unlock color' : '解除锁定';
    lockBtn.classList.toggle('locked', locked);
    lockBtn.innerHTML = locked ? TEMP_COLOR_LOCKED_SVG : TEMP_COLOR_UNLOCKED_SVG;
    lockBtn.title = locked ? unlockLabel : lockLabel;
    lockBtn.setAttribute('aria-label', lockBtn.title);
    lockBtn.setAttribute('aria-pressed', locked ? 'true' : 'false');
}

function __syncTempColorFollowLocksInDom() {
    document.querySelectorAll('.temp-color-lock-btn').forEach(btn => {
        const node = btn.closest('.temp-canvas-node');
        const sectionId = node && node.dataset ? node.dataset.sectionId : null;
        if (!sectionId) return;
        const section = getTempSection(sectionId);
        if (!section) return;
        __applyTempColorLockButtonState(btn, section);
    });
}

function __resetAllTempSectionColorsToDefault() {
    if (!Array.isArray(CanvasState.tempSections)) return;
    CanvasState.tempSections.forEach(section => {
        if (!section) return;
        updateTempSectionColor(section, getTempSectionDefaultColor(section));
    });
    try { saveTempNodes(); } catch (_) { }
    const isEn = typeof currentLang !== 'undefined' && (currentLang === 'en' || currentLang === 'en_US' || currentLang === 'en-GB' || String(currentLang).toLowerCase().startsWith('en'));
    showCanvasToast(
        isEn ? 'All temp colors reset to default.' : '已还原所有临时栏目为默认色。',
        'success'
    );
}

function __applyGlobalTempColorFollowSetting(enabled) {
    const lockAll = !enabled;
    if (!Array.isArray(CanvasState.tempSections)) return;
    let changed = false;
    CanvasState.tempSections.forEach(section => {
        if (!section) return;
        if (section.colorLocked !== lockAll) {
            section.colorLocked = lockAll;
            changed = true;
        }
    });
    if (changed) {
        __syncTempColorFollowLocksInDom();
        try { saveTempNodes(); } catch (_) { }
    }
}

function __updateOtherTempColorFollowLock(modal, enabled) {
    const target = modal ? modal.querySelector('#otherTempColorFollowLock') : document.getElementById('otherTempColorFollowLock');
    if (!target) return;
    const isOn = !!enabled;
    target.classList.toggle('is-enabled', isOn);
    target.innerHTML = isOn ? '<i class="fas fa-unlock"></i>' : '<i class="fas fa-lock"></i>';
}

function __updateOtherSidebarCollapseMode(modal) {
    if (!modal) return;
    const inputs = modal.querySelector('#otherSidebarAutoCollapseInputs');
    if (!inputs) return;
    const mode = __getAppearanceRadioValue(modal, 'other-sidebar-collapse-mode', 'auto');
    const useAuto = mode === 'auto';
    inputs.classList.toggle('is-disabled', !useAuto);
    inputs.classList.toggle('is-hidden', !useAuto);
}

function shouldUseDefaultZoomCurve() {
    const settings = getCanvasOtherSettings();
    return !(settings && settings.useDefaultZoomCurve === false);
}

const CANVAS_PERF_MANUAL_BASE_KEY = 'canvas-perf-manual-base-v1';
const CANVAS_PERF_LINKED_FROM_OTHER_KEY = 'canvas-perf-linked-from-other-v1';

function __readPerfManualBaseline() {
    try {
        const raw = localStorage.getItem(CANVAS_PERF_MANUAL_BASE_KEY);
        if (raw) {
            const parsed = JSON.parse(raw);
            if (parsed && typeof parsed === 'object') return parsed;
        }
    } catch (_) { }
    return null;
}

function __writePerfManualBaseline(payload) {
    try {
        saveSharedState(CANVAS_PERF_MANUAL_BASE_KEY, payload || {});
    } catch (_) { }
}

function __getPerfManualBaseline() {
    const saved = __readPerfManualBaseline();
    if (saved && Number.isFinite(saved.safeZone) && Number.isFinite(saved.exitLowDetail) && Number.isFinite(saved.enterLowDetail)) {
        return saved;
    }
    return {
        safeZone: getCanvasSafeZoneThreshold() * 100,
        exitLowDetail: getCanvasLowDetailPrewarmDisplayZoomThreshold() * 100,
        enterLowDetail: getCanvasLowDetailDisplayZoomThreshold() * 100
    };
}

function __ensurePerfManualBaseline() {
    if (__readPerfManualBaseline()) return;
    __writePerfManualBaseline({
        safeZone: getCanvasSafeZoneThreshold() * 100,
        exitLowDetail: getCanvasLowDetailPrewarmDisplayZoomThreshold() * 100,
        enterLowDetail: getCanvasLowDetailDisplayZoomThreshold() * 100
    });
}

function __readPerfLinkedFromOther() {
    try {
        const raw = localStorage.getItem(CANVAS_PERF_LINKED_FROM_OTHER_KEY);
        if (raw) {
            const parsed = JSON.parse(raw);
            if (parsed && typeof parsed === 'object') return parsed;
        }
    } catch (_) { }
    return null;
}

function __writePerfLinkedFromOther(payload) {
    try {
        saveSharedState(CANVAS_PERF_LINKED_FROM_OTHER_KEY, payload || {});
    } catch (_) { }
}

function __clearPerfLinkedFromOther() {
    try { localStorage.removeItem(CANVAS_PERF_LINKED_FROM_OTHER_KEY); } catch (_) { }
}

function __formatPercentInputValue(value) {
    if (!Number.isFinite(value)) return '';
    const v = Math.round(value * 10) / 10;
    return (v % 1 === 0) ? v.toFixed(0) : v.toFixed(1);
}

function __applyPerfManualBaselineToPerf() {
    const baseline = __getPerfManualBaseline();
    if (!baseline) return;
    const safeZoneSettings = (() => {
        try {
            const raw = localStorage.getItem('canvasSafeZoneSettings');
            if (raw) {
                const parsed = JSON.parse(raw);
                if (parsed && typeof parsed === 'object') return parsed;
            }
        } catch (_) { }
        return { threshold: 0.70, enabled: true };
    })();
    safeZoneSettings.threshold = baseline.safeZone / 100;
    try { saveSharedState('canvasSafeZoneSettings', safeZoneSettings); } catch (_) { }

    const zoomThresholds = {
        enterLowDetail: baseline.enterLowDetail / 100,
        exitLowDetail: baseline.exitLowDetail / 100
    };
    try { saveSharedState('canvasZoomThresholds', zoomThresholds); } catch (_) { }

    const safeInput = document.getElementById('perfInputSafeZone');
    if (safeInput) safeInput.value = __formatPercentInputValue(baseline.safeZone);
    const exitInput = document.getElementById('perfInputExitLowDetail');
    if (exitInput) exitInput.value = __formatPercentInputValue(baseline.exitLowDetail);
    const enterInput = document.getElementById('perfInputEnterLowDetail');
    if (enterInput) enterInput.value = __formatPercentInputValue(baseline.enterLowDetail);

    const safeValueEl = document.getElementById('perfMagnetSafeValue');
    if (safeValueEl) safeValueEl.textContent = `${__formatPercentInputValue(baseline.safeZone)}%`;
    const midValueEl = document.getElementById('perfMagnetMidValue');
    if (midValueEl) {
        const mid = (baseline.exitLowDetail + baseline.enterLowDetail) / 2;
        midValueEl.textContent = `${__formatPercentInputValue(mid)}%`;
    }

    __clearPerfLinkedFromOther();
    __applyPerfLinkedStyles();
}

function __applyPerfDefaultBaselineToPerf() {
    const safeZoneSettings = (() => {
        try {
            const raw = localStorage.getItem('canvasSafeZoneSettings');
            if (raw) {
                const parsed = JSON.parse(raw);
                if (parsed && typeof parsed === 'object') return parsed;
            }
        } catch (_) { }
        return { threshold: 0.70, enabled: true };
    })();
    safeZoneSettings.threshold = DEFAULT_PERF_BASELINE.safeZone / 100;
    try { saveSharedState('canvasSafeZoneSettings', safeZoneSettings); } catch (_) { }

    const zoomThresholds = {
        enterLowDetail: DEFAULT_PERF_BASELINE.enterLowDetail / 100,
        exitLowDetail: DEFAULT_PERF_BASELINE.exitLowDetail / 100
    };
    try { saveSharedState('canvasZoomThresholds', zoomThresholds); } catch (_) { }

    const safeInput = document.getElementById('perfInputSafeZone');
    if (safeInput) safeInput.value = __formatPercentInputValue(DEFAULT_PERF_BASELINE.safeZone);
    const exitInput = document.getElementById('perfInputExitLowDetail');
    if (exitInput) exitInput.value = __formatPercentInputValue(DEFAULT_PERF_BASELINE.exitLowDetail);
    const enterInput = document.getElementById('perfInputEnterLowDetail');
    if (enterInput) enterInput.value = __formatPercentInputValue(DEFAULT_PERF_BASELINE.enterLowDetail);

    const safeValueEl = document.getElementById('perfMagnetSafeValue');
    if (safeValueEl) safeValueEl.textContent = `${__formatPercentInputValue(DEFAULT_PERF_BASELINE.safeZone)}%`;
    const midValueEl = document.getElementById('perfMagnetMidValue');
    if (midValueEl) {
        const mid = (DEFAULT_PERF_BASELINE.exitLowDetail + DEFAULT_PERF_BASELINE.enterLowDetail) / 2;
        midValueEl.textContent = `${__formatPercentInputValue(mid)}%`;
    }

    __clearPerfLinkedFromOther();
    __applyPerfLinkedStyles();
}

function __applyPerfLinkedStyles() {
    const flags = __readPerfLinkedFromOther();
    const safeInput = document.getElementById('perfInputSafeZone');
    const exitInput = document.getElementById('perfInputExitLowDetail');
    const enterInput = document.getElementById('perfInputEnterLowDetail');
    const magnetSafeValue = document.getElementById('perfMagnetSafeValue');
    const magnetMidValue = document.getElementById('perfMagnetMidValue');
    const magnetTitle = document.getElementById('perfMagnetTitleText');
    const magnetJumpLabel = document.getElementById('perfMagnetJumpLabel');
    const magnetJumpBtn = document.getElementById('perfMagnetJumpOtherBtn');

    const apply = (input) => {
        if (!input) return;
        const unit = input.parentElement ? input.parentElement.querySelector('span') : null;
        if (flags) {
            input.classList.add('perf-linked-input');
            if (unit) unit.classList.add('perf-linked-text');
        } else {
            input.classList.remove('perf-linked-input');
            if (unit) unit.classList.remove('perf-linked-text');
        }
    };

    apply(safeInput);
    apply(exitInput);
    apply(enterInput);

    const toggleLinkedText = (el) => {
        if (!el) return;
        if (flags) el.classList.add('perf-linked-text');
        else el.classList.remove('perf-linked-text');
    };
    toggleLinkedText(magnetSafeValue);
    toggleLinkedText(magnetMidValue);
    toggleLinkedText(magnetTitle);

    const lang = typeof currentLang !== 'undefined' ? currentLang : 'zh';
    const isEn = lang === 'en';
    if (magnetJumpLabel) {
        magnetJumpLabel.textContent = flags
            ? (isEn ? 'Source: Other → Zoom Speed & Magnet' : '来源：其他 → 缩放速率与磁矩')
            : (isEn ? 'Go to Other → Zoom Speed & Magnet' : '跳转到其他 → 缩放速率与磁矩');
        toggleLinkedText(magnetJumpLabel);
    }
    if (magnetJumpBtn) {
        toggleLinkedText(magnetJumpBtn);
    }
}

function __syncPerfSettingsFromOtherMagnetPoints(magnetPoints) {
    __ensurePerfManualBaseline();
    const points = __normalizeMagnetPoints(magnetPoints);
    const minPercent = Math.max(1, Math.min(100, getCanvasMinZoomLimit() || 10));
    const maxPercent = 100;
    const range = Math.max(1, maxPercent - minPercent);
    const safePercent = minPercent + (__clamp01(points.m1.x) * range);
    const midPercent = minPercent + (__clamp01(points.m2.x) * range);

    let gap = 5;
    const baseline = __getPerfManualBaseline();
    const curGap = baseline.enterLowDetail - baseline.exitLowDetail;
    if (Number.isFinite(curGap) && curGap > 0) gap = curGap;
    if (!Number.isFinite(gap) || gap <= 0) gap = 5;

    let exitPercent = midPercent - gap / 2;
    let enterPercent = midPercent + gap / 2;
    const minV = 1;
    const maxV = 100;
    if (exitPercent < minV) {
        exitPercent = minV;
        enterPercent = exitPercent + gap;
    }
    if (enterPercent > maxV) {
        enterPercent = maxV;
        exitPercent = enterPercent - gap;
    }
    exitPercent = Math.max(minV, Math.min(maxV, exitPercent));
    enterPercent = Math.max(minV, Math.min(maxV, enterPercent));
    if (enterPercent < exitPercent) {
        const tmp = enterPercent;
        enterPercent = exitPercent;
        exitPercent = tmp;
    }

    const safeZoneSettings = (() => {
        try {
            const raw = localStorage.getItem('canvasSafeZoneSettings');
            if (raw) {
                const parsed = JSON.parse(raw);
                if (parsed && typeof parsed === 'object') return parsed;
            }
        } catch (_) { }
        return { threshold: 0.70, enabled: true };
    })();
    safeZoneSettings.threshold = safePercent / 100;
    try { saveSharedState('canvasSafeZoneSettings', safeZoneSettings); } catch (_) { }

    const zoomThresholds = {
        enterLowDetail: enterPercent / 100,
        exitLowDetail: exitPercent / 100
    };
    try { saveSharedState('canvasZoomThresholds', zoomThresholds); } catch (_) { }

    __writePerfLinkedFromOther({
        safeZone: safePercent,
        exitLowDetail: exitPercent,
        enterLowDetail: enterPercent,
        midPercent,
        updatedAt: Date.now()
    });

    const safeInput = document.getElementById('perfInputSafeZone');
    if (safeInput) safeInput.value = __formatPercentInputValue(safePercent);
    const exitInput = document.getElementById('perfInputExitLowDetail');
    if (exitInput) exitInput.value = __formatPercentInputValue(exitPercent);
    const enterInput = document.getElementById('perfInputEnterLowDetail');
    if (enterInput) enterInput.value = __formatPercentInputValue(enterPercent);

    const safeValueEl = document.getElementById('perfMagnetSafeValue');
    if (safeValueEl) safeValueEl.textContent = `${__formatPercentInputValue(safePercent)}%`;
    const midValueEl = document.getElementById('perfMagnetMidValue');
    if (midValueEl) midValueEl.textContent = `${__formatPercentInputValue(midPercent)}%`;

    __applyPerfLinkedStyles();
}

function __getTempSectionSizeSettings(section) {
    const settings = getCanvasAppearanceSettings();
    const sizes = settings.sizes || DEFAULT_CANVAS_APPEARANCE_SETTINGS.sizes;
    // 只要被识别为“特殊临时栏目”，尺寸就自动切到 specialTemp。
    if (section && __isSpecialTempSection(section)) {
        return sizes.specialTemp || DEFAULT_CANVAS_APPEARANCE_SETTINGS.sizes.specialTemp || sizes.temp;
    }
    return sizes.temp || DEFAULT_CANVAS_APPEARANCE_SETTINGS.sizes.temp;
}

function getSpecialTempSectionDefaultColor() {
    const settings = getCanvasAppearanceSettings();
    return (settings.colors && settings.colors.specialTemp) ? settings.colors.specialTemp : '#e9973f';
}

function getTempSectionBaseSize(section = null) {
    const size = __getTempSectionSizeSettings(section);
    return { width: size.width, height: size.height, mode: size.mode || 'manual' };
}

function getPermanentSectionBaseSize() {
    const settings = getCanvasAppearanceSettings();
    const size = settings.sizes && settings.sizes.permanent ? settings.sizes.permanent : DEFAULT_CANVAS_APPEARANCE_SETTINGS.sizes.permanent;
    return { width: size.width, height: size.height, mode: 'manual' };
}

function getBlankNodeDefaultSize() {
    const settings = getCanvasAppearanceSettings();
    const size = settings.sizes && settings.sizes.mdNode ? settings.sizes.mdNode : DEFAULT_CANVAS_APPEARANCE_SETTINGS.sizes.mdNode;
    return { width: size.width, height: size.height };
}

function getTempSectionDefaultColor(section = null) {
    // 只要被识别为“特殊临时栏目”，默认颜色就自动切到 specialTemp。
    if (section && __isSpecialTempSection(section)) {
        return getSpecialTempSectionDefaultColor();
    }
    const settings = getCanvasAppearanceSettings();
    return (settings.colors && settings.colors.temp) ? settings.colors.temp : TEMP_SECTION_DEFAULT_COLOR;
}

function getBlankNodeDefaultColor() {
    const settings = getCanvasAppearanceSettings();
    return (settings.colors && settings.colors.mdNode) ? settings.colors.mdNode : '#888888';
}

function getEdgeDefaultColor() {
    const settings = getCanvasAppearanceSettings();
    return (settings.colors && settings.colors.edge) ? settings.colors.edge : '#999999';
}

function getPermanentSectionDefaultColor() {
    const settings = getCanvasAppearanceSettings();
    return (settings.colors && settings.colors.permanent) ? settings.colors.permanent : '#10b981';
}

function syncMarkerBadgeColorToBackgroundStorage(colorHex) {
    try {
        if (!browserAPI || !browserAPI.storage || !browserAPI.storage.local || typeof browserAPI.storage.local.set !== 'function') return;
        browserAPI.storage.local.set({
            [CANVAS_MARKER_BADGE_COLOR_STORAGE_KEY]: colorHex
        }, () => {
            try {
                const err = browserAPI && browserAPI.runtime ? browserAPI.runtime.lastError : null;
                if (err && err.message) {
                    // ignore
                }
            } catch (_) { }
        });
    } catch (_) { }
}

function applyMarkerBadgeColorVars(color) {
    const hex = __normalizeAppearanceColor(color, DEFAULT_MARKER_BADGE_COLOR);
    const rgb = hexToRgb(hex) || { r: 251, g: 188, b: 4 };
    const iconColor = lightenHexColor(hex, 0.22);
    const iconColorDark = lightenHexColor(hex, 0.34);
    const textColor = pickReadableTextColor(hex);
    __setCssVar('--marker-badge-color', hex);
    __setCssVar('--marker-badge-color-rgb', `${rgb.r}, ${rgb.g}, ${rgb.b}`);
    __setCssVar('--marker-badge-icon-color', iconColor);
    __setCssVar('--marker-badge-icon-color-dark', iconColorDark);
    __setCssVar('--marker-badge-text-color', textColor);
    syncMarkerBadgeColorToBackgroundStorage(hex);
}

function __setCssVar(name, value) {
    try {
        if (document && document.documentElement) {
            document.documentElement.style.setProperty(name, value);
        }
    } catch (_) { }
}

function applyPermanentSectionColorVars(color) {
    const hex = __normalizeAppearanceColor(color, '#10b981');
    const rgb = hexToRgb(hex) || { r: 16, g: 185, b: 129 };
    const dark = darkenHexColor(hex, 0.18);
    __setCssVar('--permanent-section-color', hex);
    __setCssVar('--permanent-section-color-dark', dark);
    __setCssVar('--permanent-section-color-rgb', `${rgb.r}, ${rgb.g}, ${rgb.b}`);
}

function applyCanvasAppearanceSettings(settings, options = {}) {
    if (!settings) return;
    const edgePreviewColor = __normalizeAppearanceColor(settings.colors && settings.colors.edge, '#999999');
    applyPermanentSectionColorVars(settings.colors && settings.colors.permanent);
    applyMarkerBadgeColorVars(settings.colors && settings.colors.markerBadge);
    __setCssVar('--appearance-edge-color-preview', edgePreviewColor);
    if (options && options.applyPermanentSize) {
        applyPermanentSectionSizeFromAppearance(settings, { force: true });
    }
}

