    const item2 = isEn ? '✓ Canvas layout & connections' : '✓ 画布布局与连接线';
    const item3 = isEn ? '✓ Scroll positions & settings' : '✓ 滚动位置与设置';
    const item4 = isEn ? '✓ Structured JSON for AI analysis' : '✓ 结构化 JSON（便于 AI 分析）';
